import { AUTH_KEY } from '@/constants'
import * as SecureStore from 'expo-secure-store'
import { create } from 'zustand'
import { useOrganizationStore } from './organizationStore'
import { z } from 'zod'
import Purchases from 'react-native-purchases'
import { jwtDecode } from 'jwt-decode'
import { Platform } from 'react-native'
import { apolloCache } from '@/utils/apollo'

const authSchema = z.object({
	accessToken: z.string(),
	refreshToken: z.string()
})

type Auth = z.infer<typeof authSchema>

interface AuthStore {
	isReady: boolean
	auth: Auth | null
	setAuth: (auth: Auth | null) => void
	init: (rawAuth: string | null) => void
}

export const useAuthStore = create<AuthStore>((set) => ({
	isReady: false,
	auth: null,
	setAuth: (auth: Auth | null) => {
		if (auth) {
			SecureStore.setItemAsync(AUTH_KEY, JSON.stringify(auth))
		} else {
			useOrganizationStore.getState().setCurrentOrganizationIndex(0)
			SecureStore.deleteItemAsync(AUTH_KEY)
		}
		set({ auth })
	},
	init: (rawAuth: string | null) => {
		const auth = rawAuth ? authSchema.safeParse(JSON.parse(rawAuth)) : null

		useAuthStore.setState({
			auth: auth?.success ? auth.data : null,
			isReady: true
		})
	}
}))

useAuthStore.subscribe(async (state) => {
	if (
		Platform.OS === 'ios' &&
		process.env.EXPO_PUBLIC_REVENUECAT_PROJECT_APPLE_API_KEY
	) {
		try {
			if (state.auth) {
				const { sub } = jwtDecode(state.auth.accessToken)
				if (typeof sub === 'string') {
					await Purchases.logIn(sub)
				}
			} else {
				apolloCache.reset()
				await Purchases.logOut()
			}
		} catch (error) {
			console.warn('Error logging in/out of Purchases:', error)
		}
	}
})
